#include "gear/GearFamilyRuntime.hpp"
#include "core/Saturating.hpp"
#include <array>
namespace elysium::gear {namespace{constexpr std::uint64_t Provider=0x4745415246414dULL;}
bool GearFamilyRuntime::publish(GearModuleDefinition d,reason::ReasonStack*r){reason::ReasonStack q;if(!d.moduleId||d.occupies.empty())q.add({reason::ReasonCode::InvalidRequest,Provider,d.moduleId,0});d.powerDraw=safe::nonNegative(d.powerDraw);d.oxygenModifier=safe::finiteClamp(d.oxygenModifier,-safe::PublishedScalarCeiling,safe::PublishedScalarCeiling);d.hazardShieldModifier=safe::finiteClamp(d.hazardShieldModifier,-safe::PublishedScalarCeiling,safe::PublishedScalarCeiling);d.carryModifier=safe::finiteClamp(d.carryModifier,-safe::PublishedScalarCeiling,safe::PublishedScalarCeiling);d.toolEnergyModifier=safe::finiteClamp(d.toolEnergyModifier,-safe::PublishedScalarCeiling,safe::PublishedScalarCeiling);if(r)r->append(q);if(q.blocked())return false;return defs_.emplace(d.moduleId,std::move(d)).second;}
GearLoadoutEvaluation GearFamilyRuntime::evaluate(const std::vector<EquippedModule>&ls)const{GearLoadoutEvaluation o{};std::array<StableId,8>occupied{};for(const auto&e:ls){if(!e.enabled)continue;auto it=defs_.find(e.moduleId);if(it==defs_.end()){o.reasons.add({reason::ReasonCode::UnknownContent,Provider,e.moduleId,0});continue;}for(auto c:it->second.occupies){auto i=static_cast<std::size_t>(c);if(occupied[i]&&occupied[i]!=e.itemId)o.reasons.add({reason::ReasonCode::ReservationConflict,Provider,e.itemId,10});else occupied[i]=e.itemId;}o.powerDraw=safe::nonNegative(o.powerDraw+it->second.powerDraw);o.oxygenModifier=safe::finiteClamp(o.oxygenModifier+it->second.oxygenModifier,-safe::PublishedScalarCeiling,safe::PublishedScalarCeiling);o.hazardShieldModifier=safe::finiteClamp(o.hazardShieldModifier+it->second.hazardShieldModifier,-safe::PublishedScalarCeiling,safe::PublishedScalarCeiling);o.carryModifier=safe::finiteClamp(o.carryModifier+it->second.carryModifier,-safe::PublishedScalarCeiling,safe::PublishedScalarCeiling);o.toolEnergyModifier=safe::finiteClamp(o.toolEnergyModifier+it->second.toolEnergyModifier,-safe::PublishedScalarCeiling,safe::PublishedScalarCeiling);}o.valid=!o.reasons.blocked();return o;}
} // namespace elysium::gear
